12: [{ k: 'line', ja: '文', en: 'the line', clip: 'm12_line', sim: 1600 }, { k: 'replies', ja: '返事 1・2・3', en: 'the three replies', clip: 'm12_replies', sim: 3400 }, { k: 'ans', ja: '解答', en: 'answer time', wait: 6000, sim: 5000 }],
