const BASE = { view: 'intro', live: false, sec: 0, i: 0, answers: {}, flags: {}, t: SECS[0].total, used: [null], sheet: false, quit: false, paused: false, noStart: false, timeUp: false, next: 1, bt: 60, checkP: 0, checking: false, checkMs: 2000, checkSound: true, sound: false, li: 0, ph: 0, pt: 0, tab: 0, open: null };
